        "steps": [],
        "listItems": [
          "<strong>Confundir la cosecante con el seno.</strong> El seno es [[a/c]]; la cosecante es [[c/a]]. Qué sale mal: informar 0.6 para un triángulo 3-4-5. Corrección: ponga la hipotenusa arriba.",
          "<strong>Invertir la fórmula a [[a/c]] en lugar de [[c/a]].</strong> Qué sale mal: la respuesta es el seno, siempre por debajo de 1. Corrección: compruebe que el lado más largo sea el numerador.",
          "<strong>Confundir la cosecante con la secante.</strong> La secante es [[c/b]], el recíproco del coseno. Qué sale mal: usar el cateto adyacente. Corrección: la cosecante se empareja con el seno y el cateto opuesto.",
          "<strong>Usar el cateto adyacente en lugar del cateto opuesto.</strong> Qué sale mal: calcular [[c/b]] por error. Corrección: confirme el lado opuesto al ángulo [[A]] antes de dividir.",
          "<strong>Suponer que la cosecante se mide en grados.</strong> Qué sale mal: escribir 1.6667 grados. Corrección: la razón es un número puro, no un ángulo.",
          "<strong>Informar una razón cosecante con metros o centímetros.</strong> Qué sale mal: las unidades ya se cancelaron. Corrección: quite la unidad de la respuesta.",
          "<strong>Aceptar un resultado menor que 1 para un triángulo válido.</strong> Qué sale mal: confiar en un cálculo con entradas intercambiadas. Corrección: un resultado válido siempre supera 1.",
          "<strong>Introducir una hipotenusa más corta que el cateto opuesto.</strong> Qué sale mal: las entradas describen un triángulo imposible. Corrección: el campo de la hipotenusa debe contener la medida más larga.",
          "<strong>Introducir longitudes de lados cero o negativas.</strong> Qué sale mal: división por cero o una razón negativa sin sentido. Corrección: use solo longitudes positivas.",
          "<strong>Mezclar unidades de medida.</strong> Qué sale mal: centímetros divididos entre metros sesgan la razón en un factor de 100. Corrección: convierta ambos lados a una unidad primero.",
          "<strong>Redondear demasiado pronto.</strong> Qué sale mal: redondear [[5/3]] a 1.67 antes de volver a multiplicar añade un error evitable. Corrección: conserve la fracción o dígitos extra hasta el paso final.",
          "<strong>Confundir el ángulo de referencia con el otro ángulo agudo.</strong> Qué sale mal: las etiquetas de opuesto y adyacente se intercambian. Corrección: marque primero el ángulo [[A]] en el diagrama.",
          "<strong>Suponer que una razón cosecante grande es un ángulo.</strong> Qué sale mal: leer 12.6667 como grados. Corrección: es un multiplicador, por lo que la hipotenusa es 12.6667 veces el cateto opuesto.",
          "<strong>Suponer que la cosecante por sí sola determina la hipotenusa.</strong> Qué sale mal: esperar que un número produzca una longitud. Corrección: la razón también necesita el cateto opuesto, mediante [[c=a\\times\\csc(A)]].",
          "<strong>Confundir el recíproco del seno con el recíproco del coseno.</strong> Qué sale mal: usar la secante donde corresponde la cosecante. Corrección: el seno se empareja con la cosecante; el coseno se empareja con la secante."
        ],
