            "alt": "Три этапа: треугольник 3-4-5, синус 3/5=0.6, косеканс 5/3=1.6667, тождество csc(A)=1/sin(A)",
            "caption": "Синус и косеканс взаимно обратны: переворот 3/5 даёт 5/3, и csc(A) = 1/sin(A)."
