        "blocks": [
          {
            "kind": "p",
            "text": "Пошаговое описание ниже соответствует фактическому интерфейсу на этой странице."
          },
          {
            "kind": "p",
            "text": "Обратите внимание, чего калькулятор никогда не просит: ни угла [[A]] в градусах, ни прилежащего катета, ни значения синуса. Двух длин сторон достаточно для полного ввода, потому что отношение [[c/a]] ни от чего другого не зависит."
          }
        ],
        "steps": [
          "<strong>Определите опорный угол [[A]].</strong> Решите, какой острый угол описывает отношение, поскольку противолежащий катет определён относительно него.",
          "<strong>Найдите гипотенузу [[c]].</strong> Это сторона, лежащая напротив прямого угла, и самая длинная сторона треугольника.",
          "<strong>Найдите противолежащий катет [[a]].</strong> Это сторона, расположенная прямо напротив угла [[A]].",
          "<strong>Измерьте или получите обе длины сторон.</strong> Используйте рулетку, чертёж или заданные данные, сохраняя для обоих одну и ту же единицу.",
          "<strong>Введите гипотенузу в первое поле ввода.</strong> Это большее из двух значений.",
          "<strong>Введите противолежащий катет во второе поле ввода.</strong> Это меньшее из двух значений.",
          "<strong>Выберите совместимые единицы с помощью селекторов единиц.</strong> Оба поля должны использовать одну и ту же единицу, чтобы деление было осмысленным.",
          "<strong>Убедитесь, что оба значения положительны.</strong> Нулевые или отрицательные длины не могут образовать треугольник.",
          "<strong>Проверьте, что гипотенуза длиннее противолежащего катета.</strong> Если это не так, вводы перепутаны или неверно подписаны.",
          "<strong>Нажмите Рассчитать csc(A).</strong> Инструмент делит гипотенузу на противолежащий катет.",
          "<strong>Прочитайте полученное отношение косеканса.</strong> Это безразмерное число, описывающее гипотенузу как кратное противолежащего катета.",
          "<strong>Убедитесь, что ответ больше 1.</strong> Любое значение, равное 1 или ниже, сигнализирует об ошибке ввода.",
          "<strong>Используйте Reset, чтобы очистить ввод</strong> и начать новый расчёт."
        ],
