        "question": "Какая формула косеканса в прямоугольном треугольнике?",
        "answer": "Формула: csc(A) = c / a: разделите гипотенузу на сторону, противолежащую углу A. Для гипотенузы 5 и противолежащей стороны 3 результат равен 5/3, примерно 1.6667. То же значение даёт обратное тождество csc(A) = 1 / sin(A)."
