          {
            "alt": "Rechtwinkliges Dreieck mit Winkel A unten links, goldener Gegenkathete a, blauer Ankathete b, rosafarbener Hypotenuse c, Formel csc(A)=c/a",
            "caption": "Der Winkel A sitzt unten links; der Kosekans verwendet die Hypotenuse c und die Gegenkathete a, nicht die Ankathete b."
          }
