        "steps": [],
        "listItems": [
          "<strong>Kosekans mit Sinus verwechseln.</strong> Der Sinus ist [[a/c]]; der Kosekans ist [[c/a]]. Was schiefgeht: 0,6 für ein 3-4-5-Dreieck melden. Korrektur: Die Hypotenuse nach oben stellen.",
          "<strong>Die Formel zu [[a/c]] statt [[c/a]] umkehren.</strong> Was schiefgeht: Die Antwort ist der Sinus, immer unter 1. Korrektur: Prüfen, dass die längere Seite der Zähler ist.",
          "<strong>Kosekans mit Sekans verwechseln.</strong> Der Sekans ist [[c/b]], der Kehrwert des Kosinus. Was schiefgeht: Die Ankathete verwenden. Korrektur: Der Kosekans paart sich mit dem Sinus und der Gegenkathete.",
          "<strong>Die Ankathete statt der Gegenkathete verwenden.</strong> Was schiefgeht: Fälschlich [[c/b]] berechnen. Korrektur: Die Seite gegenüber dem Winkel [[A]] vor dem Dividieren bestätigen.",
          "<strong>Annehmen, dass der Kosekans in Grad gemessen wird.</strong> Was schiefgeht: 1,6667 Grad schreiben. Korrektur: Das Verhältnis ist eine reine Zahl, kein Winkel.",
          "<strong>Ein Kosekans-Verhältnis mit Metern oder Zentimetern melden.</strong> Was schiefgeht: Die Einheiten waren bereits gekürzt. Korrektur: Die Einheit aus der Antwort entfernen.",
          "<strong>Ein Ergebnis unter 1 für ein gültiges Dreieck akzeptieren.</strong> Was schiefgeht: Einer Berechnung mit vertauschter Eingabe vertrauen. Korrektur: Ein gültiges Ergebnis übersteigt immer 1.",
          "<strong>Eine Hypotenuse eingeben, die kürzer ist als die Gegenkathete.</strong> Was schiefgeht: Die Eingaben beschreiben ein unmögliches Dreieck. Korrektur: Das Hypotenusen-Feld muss die längere Messung enthalten.",
          "<strong>Null- oder negative Seitenlängen eingeben.</strong> Was schiefgeht: Division durch null oder ein sinnloses negatives Verhältnis. Korrektur: Nur positive Längen verwenden.",
          "<strong>Messeinheiten mischen.</strong> Was schiefgeht: Zentimeter geteilt durch Meter verfälschen das Verhältnis um den Faktor 100. Korrektur: Zuerst beide Seiten in eine Einheit umrechnen.",
          "<strong>Zu früh runden.</strong> Was schiefgeht: [[5/3]] vor dem Zurückmultiplizieren auf 1,67 zu runden, fügt vermeidbaren Fehler hinzu. Korrektur: Den Bruch oder zusätzliche Stellen bis zum letzten Schritt behalten.",
          "<strong>Den Bezugswinkel mit dem anderen spitzen Winkel verwechseln.</strong> Was schiefgeht: Die Gegen- und Ankatheten-Bezeichnungen vertauschen sich. Korrektur: Zuerst den Winkel [[A]] im Diagramm markieren.",
          "<strong>Annehmen, dass ein großes Kosekans-Verhältnis ein Winkel ist.</strong> Was schiefgeht: 12,6667 als Grad lesen. Korrektur: Es ist ein Multiplikator, sodass die Hypotenuse 12,6667-mal so lang ist wie die Gegenkathete.",
          "<strong>Annehmen, dass der Kosekans allein die Hypotenuse bestimmt.</strong> Was schiefgeht: Erwarten, dass eine Zahl eine Länge liefert. Korrektur: Das Verhältnis braucht auch die Gegenkathete, über [[c=a\\times\\csc(A)]].",
          "<strong>Den Kehrwert des Sinus mit dem Kehrwert des Kosinus verwechseln.</strong> Was schiefgeht: Den Sekans verwenden, wo der Kosekans hingehört. Korrektur: Der Sinus paart sich mit dem Kosekans; der Kosinus paart sich mit dem Sekans."
        ],
